// CreditCardDetails.js (Frontend - React)
import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './CreditCardDetails.css'; // Create this CSS file

function CreditCardDetails() {
    const [cardNumber, setCardNumber] = useState('');
    const [expiryDate, setExpiryDate] = useState('');
    const [cvv, setCvv] = useState('');
    const [cardHolderName, setCardHolderName] = useState('');
    const [message, setMessage] = useState('');
    const email = localStorage.getItem('email');



    useEffect(() => {
        const generateCardNumber = () => {
            let number = '';
            for (let i = 0; i < 16; i++) { // Generate a 16-digit number
                number += Math.floor(Math.random() * 10);
            }

            setCardNumber(number);
        };
        generateCardNumber();

    }, []);



    const handleSubmit = async (e) => {
        e.preventDefault();

        try {
            await axios.post('http://localhost:8000/credit-card', {  // New route
                email,
                cardNumber,
                expiryDate,
                cvv,
                cardHolderName,

            });

            setMessage('Credit card details saved successfully!');
            // Clear form after successful submission or redirect as needed


        } catch (error) {

            setMessage('Error saving credit card details. Please try again.');
            console.error("Error saving credit card:", error);


        }
    }


    return (
        <div className="credit-card-container">
            <h2>Credit Card Details</h2>
            <form onSubmit={handleSubmit}>

                <div>
                    <label htmlFor="cardNumber">Card Number:</label>
                    <input
                        type="text"
                        id="cardNumber"
                        value={cardNumber}
                        onChange={(e) => setCardNumber(e.target.value)} // Allow changes if needed
                        readOnly // Make it read-only initially 
                    />
                </div>

                <div>
                    <label htmlFor="expiryDate">Expiry Date (MM/YY):</label>
                    <input
                        type="text"
                        id="expiryDate"
                        placeholder="MM/YY"
                        value={expiryDate}
                        onChange={(e) => setExpiryDate(e.target.value)}
                        pattern="\d{2}/\d{2}" // Basic format validation
                        required
                    />
                </div>

                <div>
                    <label htmlFor="cvv">CVV:</label>
                    <input
                        type="text" // or type="number" if you prefer
                        id="cvv"
                        value={cvv}
                        onChange={(e) => setCvv(e.target.value)}
                        maxLength="3" // Restrict to 3 digits
                        required
                    />
                </div>
                <div>
                    <label htmlFor="cardHolderName">Cardholder Name:</label>
                    <input
                        type="text"
                        id="cardHolderName"
                        value={cardHolderName}
                        onChange={(e) => setCardHolderName(e.target.value)}
                        required
                    />

                </div>
                <button type="submit">Save</button>
            </form>

            {message && <p>{message}</p>}
        </div>
    );
}

export default CreditCardDetails;
